<?php
namespace App\Domain\CaseStudies;
use App\Models\CaseStudy; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
final class CaseStudyManager { public function save(array $data,?CaseStudy $item,int $userId):CaseStudy{return DB::transaction(function()use($data,$item,$userId){$item??=new CaseStudy;$data['updated_by']=$userId;if(!$item->exists){$data['created_by']=$userId;$data['status']='draft';$data['display_order']=(int)CaseStudy::max('display_order')+1;}else{unset($data['status']);}$item->fill($data)->save();return $item;});} public function publish(CaseStudy $item):void{$item->update(['status'=>'published','published_at'=>now(),'scheduled_for'=>null,'archived_at'=>null]);} public function schedule(CaseStudy $item,string $utc):void{$item->update(['status'=>'scheduled','scheduled_for'=>$utc,'published_at'=>null,'archived_at'=>null]);} public function unpublish(CaseStudy $item):void{$item->update(['status'=>'draft','published_at'=>null,'scheduled_for'=>null,'archived_at'=>null]);} public function archive(CaseStudy $item):void{$item->update(['status'=>'archived','archived_at'=>now(),'published_at'=>null,'scheduled_for'=>null]);} public function restore(CaseStudy $item):void{$item->update(['status'=>'draft','archived_at'=>null,'published_at'=>null,'scheduled_for'=>null]);} public function duplicate(CaseStudy $item,int $userId):CaseStudy{$copy=$item->replicate(['status','published_at','scheduled_for','archived_at','created_by','updated_by']); $copy->slug=$this->uniqueSlug($item->slug.'-copy');$copy->title.=' (Copy)';$copy->status='draft';$copy->created_by=$copy->updated_by=$userId;$copy->display_order=(int)CaseStudy::max('display_order')+1;$copy->save();return $copy;} public function move(CaseStudy $item,string $direction):void{DB::transaction(function()use($item,$direction){$peer=CaseStudy::where('display_order',$direction==='up'?'<':'>',$item->display_order)->orderBy('display_order',$direction==='up'?'desc':'asc')->first();if($peer){$order=$item->display_order;$item->update(['display_order'=>$peer->display_order]);$peer->update(['display_order'=>$order]);}});} private function uniqueSlug(string $base):string{$base=Str::slug($base)?:'case-study';$slug=$base;for($i=2;CaseStudy::where('slug',$slug)->exists();$i++){$slug="$base-$i";}return $slug;} }
